/**
 * renderDocument: TfDocument → HCL text. The single emitter (plan §4.1) —
 * `elementum build` output and the round-trip check both flow through here.
 *
 * Formatting is OURS (deterministic, 2-space indent, attrs sorted
 * alphabetically) — ei's incidental formatting is not replicated; the
 * round-trip check is structural, both sides parsed by the same parser.
 * The ei dialect is attributes-only (verified across real exports), so no
 * nested-block syntax is emitted.
 */
import { quoteHclString } from "./escape.js";
import { isTfExpr } from "./model.js";
export function renderDocument(doc) {
    return doc.blocks.map(renderBlock).join("\n");
}
export function renderBlock(block) {
    const header = blockHeader(block);
    const body = Object.entries(block.attrs)
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
        .map(([key, value]) => `  ${key} = ${renderValue(value, 1)}`)
        .join("\n");
    return `${header} {\n${body}\n}\n`;
}
function blockHeader(block) {
    switch (block.kind) {
        case "resource":
        case "data":
            return `${block.kind} ${quoteLabel(block.type)} ${quoteLabel(block.label)}`;
        case "provider":
            return `provider ${quoteLabel(block.label)}`;
        case "variable":
            return `variable ${quoteLabel(block.label)}`;
        case "locals":
        case "import":
        case "terraform":
            return block.kind;
    }
}
function quoteLabel(s) {
    if (!s)
        throw new Error("block is missing a required type/label");
    return JSON.stringify(s);
}
function renderValue(value, depth) {
    if (isTfExpr(value))
        return renderExpr(value, depth);
    if (value === null)
        return "null";
    if (typeof value === "boolean" || typeof value === "number")
        return String(value);
    if (typeof value === "string")
        return quoteHclString(value);
    const indent = "  ".repeat(depth + 1);
    const close = "  ".repeat(depth);
    if (Array.isArray(value)) {
        if (value.length === 0)
            return "[]";
        const items = value.map((v) => `${indent}${renderValue(v, depth + 1)},`).join("\n");
        return `[\n${items}\n${close}]`;
    }
    const entries = Object.entries(value);
    if (entries.length === 0)
        return "{}";
    const body = entries
        .map(([k, v]) => `${indent}${objectKey(k)} = ${renderValue(v, depth + 1)}`)
        .join("\n");
    return `{\n${body}\n${close}}`;
}
const BARE_KEY_RE = /^[A-Za-z_][A-Za-z0-9_-]*$/;
function objectKey(k) {
    return BARE_KEY_RE.test(k) ? k : quoteHclString(k);
}
function renderExpr(e, depth) {
    switch (e.$expr) {
        case "resource-attr":
            return `${e.type}.${e.label}${renderPath(e.path)}`;
        case "data-attr":
            return `data.${e.type}.${e.label}${renderPath(e.path)}`;
        case "local":
            return `local.${e.name}${renderPath(e.path)}`;
        case "variable":
            return `var.${e.name}${renderPath(e.path)}`;
        case "jsonencode":
            return `jsonencode(${renderValue(e.value, depth)})`;
        case "template": {
            const inner = e.parts
                .map((p) => (typeof p === "string" ? escapeTemplateLiteral(p) : `\${${renderExpr(p, depth)}}`))
                .join("");
            return `"${inner}"`;
        }
        case "scoped-attr":
            return `${e.name}${renderPath(e.path)}`;
        case "for-object":
            return `{ for ${e.variable} in ${renderExpr(e.collection, depth)} : ${renderExpr(e.key, depth)} => ${renderExpr(e.value, depth)} }`;
    }
}
function renderPath(path) {
    return path
        .map((seg) => (typeof seg === "string" ? `.${seg}` : `[${quoteHclString(seg.index)}]`))
        .join("");
}
/** Literal text inside a template: quote-string escapes + template doubling, no outer quotes. */
function escapeTemplateLiteral(s) {
    const quoted = quoteHclString(s);
    return quoted.slice(1, -1);
}
